#ifndef CACHE_HPP
#define CACHE_HPP

#include <cstddef>
#include <cstdint>
#include <vector>

/* An address, taken apart the way a cache takes it apart. */
struct Decoded {
    std::uint64_t tag = 0;
    std::uint64_t index = 0;
    std::uint64_t offset = 0;
};

/* A cache of `sets` sets, `ways` lines per set and `blockBytes` bytes
 * per line. `sets` and `blockBytes` are powers of two; `ways` is at
 * least 1.
 *
 * The PUBLIC part is the contract. main.cpp is written against exactly
 * these names and these signatures, so changing one stops it linking.
 * Everything under `private:` is yours.
 */
class Cache {
public:
    Cache(std::size_t sets, std::size_t ways, std::size_t blockBytes);

    std::size_t sets() const;
    std::size_t ways() const;
    std::size_t blockBytes() const;

    /* The three fields of `addr`, for this geometry. */
    Decoded decode(std::uint64_t addr) const;

    /* A read. True on a hit. A miss brings the block in, so the same
     * address read twice in a row hits the second time. */
    bool access(std::uint64_t addr);

    std::size_t hits() const;
    std::size_t misses() const;

    /* How many times a VALID line was thrown out to make room. Filling
     * a way that was never used is not an eviction. */
    std::size_t evictions() const;

private:
    std::size_t sets_;
    std::size_t ways_;
    std::size_t block_;
    std::size_t offsetBits_ = 0;
    std::size_t indexBits_ = 0;
    std::size_t hits_ = 0;
    std::size_t misses_ = 0;
    std::size_t evictions_ = 0;

    /* One line. `stamp` is whatever you need it to be to answer "which
     * of these was used longest ago". */
    struct Line {
        bool valid = false;
        bool dirty = false;
        std::uint64_t tag = 0;
        std::uint64_t stamp = 0;
    };

    std::vector<Line> lines_;
    std::uint64_t clock_ = 0;
};

#endif

#include "../include/cache.hpp"

/* The geometry, which is already done for you: how many low bits pick a
 * byte inside a block, and how many above those pick a set. `n` is a
 * power of two, so this is the position of its only 1 bit.
 */
static std::size_t log2of(std::size_t n) {
    std::size_t k = 0;
    while ((std::size_t{1} << k) < n) ++k;
    return k;
}

Cache::Cache(std::size_t sets, std::size_t ways, std::size_t blockBytes)
    : sets_(sets), ways_(ways), block_(blockBytes),
      offsetBits_(log2of(blockBytes)), indexBits_(log2of(sets)),
      lines_(sets * ways) {}

std::size_t Cache::sets() const { return sets_; }
std::size_t Cache::ways() const { return ways_; }
std::size_t Cache::blockBytes() const { return block_; }

std::size_t Cache::hits() const { return hits_; }
std::size_t Cache::misses() const { return misses_; }
std::size_t Cache::evictions() const { return evictions_; }

/* Milestone 2: ways, and a replacement policy.
 *
 * `decode` is carried forward from milestone 1 if you wrote one; this
 * is what you get if you did not. `access` now has a set of `ways_`
 * lines to search, and something to choose when they are all in use.
 */

Decoded Cache::decode(std::uint64_t addr) const {
    /* your code here — the lowest offsetBits_ bits are the offset, the
       next indexBits_ bits above those are the index, and everything
       left over is the tag. Mind the geometry where one of the two bit
       counts is zero: shifting a 64-bit value by 64 is not "shift it
       all away", it is undefined behaviour. */
    (void) addr;
    return Decoded{};
}

bool Cache::access(std::uint64_t addr) {
    /* your code here — search the ways of this set for a valid line
       whose tag matches. On a miss: fill a way that was never used if
       there is one, and otherwise throw out the least recently used
       line and count that as an eviction. */
    (void) addr;
    return false;
}

/* GIVEN, and read-only: the driver.
 *
 * It reads a geometry, then one command per line, and prints what your
 * cache said. It is the thing src/cache.cpp has to satisfy, which is
 * why you cannot edit it here — a test you can edit is not a test.
 *
 * Every address is hexadecimal, with or without an 0x in front.
 */
#include <iostream>
#include <sstream>
#include <string>

#include "include/cache.hpp"

static void printDecoded(const Decoded& d) {
    std::cout << std::hex
              << "tag=" << d.tag
              << " index=" << d.index
              << " offset=" << d.offset
              << std::dec << '\n';
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::size_t sets = 0, ways = 0, block = 0;
    if (!(std::cin >> sets >> ways >> block)) return 0;
    Cache cache(sets, ways, block);

    std::string line;
    std::getline(std::cin, line);

    while (std::getline(std::cin, line)) {
        std::istringstream in(line);
        std::string cmd;
        if (!(in >> cmd)) continue;
        std::uint64_t addr = 0;

        if (cmd == "decode") {
            if (!(in >> std::hex >> addr)) continue;
            printDecoded(cache.decode(addr));
        } else if (cmd == "read") {
            if (!(in >> std::hex >> addr)) continue;
            std::cout << (cache.access(addr) ? "hit" : "miss") << '\n';
        } else if (cmd == "stats") {
            std::cout << cache.hits() << " hits, "
                      << cache.misses() << " misses, "
                      << cache.evictions() << " evictions" << '\n';
        }
    }
    return 0;
}
